INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(139302, 6943, 3080, '<td valign="top">This is an excelent journalism or documentary photo.  Your focus and clarity are great.  The detail shown here is amazing.  I like that he''s looking right at you.  while I it an excelent photo though, I see nothing of how this relates to wrath.  I wasn''t there so I would have no prior knowledge of what he was talking about, so I do not see this as wrathful at all.  Pride and greed possibly.  Your angle and framing/cropping are great, and the lighting conditions were perfect.  Nice shot. Good luck in the challenge. ~Hbunch7187~</td>', 'This is an excelent journalism or documentary photo.  Your focus and clarity are great.  The detail shown here is amazing.  I like that he''s looking right at you.  while I it an excelent photo though, I see nothing of how this relates to wrath.  I wasn''t there so I would have no prior knowledge of what he was talking about, so I do not see this as wrathful at all.  Pride and greed possibly.  Your angle and framing/cropping are great, and the lighting conditions were perfect.  Nice shot. Good luck in the challenge. ~Hbunch7187~', '2002-10-20 13:15:00.000000', NULL, 1),
(139303, 6943, 671, '<td valign="top">Right on!!!!</td>', 'Right on!!!!', '2002-10-20 13:22:00.000000', NULL, 1),
(139304, 6943, 245, '<td valign="top">I''d like it a lot more if he were 5% further away from the left of the photo! Good timing.</td>', 'I''d like it a lot more if he were 5% further away from the left of the photo! Good timing.', '2002-10-20 16:13:00.000000', NULL, 1),
