INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(143107, 7138, 4426, '<td valign="top">Very well seen and titled. All you needed was the guy to be looking in this window!</td>', 'Very well seen and titled. All you needed was the guy to be looking in this window!', '2002-10-14 09:38:00.000000', NULL, 1),
(143108, 7138, 4608, '<td valign="top">Nice composition.  I''m a sucker for B&amp;W photos</td>', 'Nice composition.  I''m a sucker for B&W photos', '2002-10-14 12:58:00.000000', NULL, 1),
(143109, 7138, 3127, '<td valign="top">Incredible depth of field and the double entendre of the title is great.  The black and white makes for a nice effect - one that I wish more photographers had tried in this challenge.</td>', 'Incredible depth of field and the double entendre of the title is great.  The black and white makes for a nice effect - one that I wish more photographers had tried in this challenge.', '2002-10-14 13:40:00.000000', NULL, 1),
(143110, 7138, 1041, '<td valign="top">challenge -- met<br/>technical -- good.  i do wonder though why you chose b&amp;w.  but maybe it would be clear if i saw the color version ;)<br/>composition -- i''m not sure exactly how i would change this, but i feel that i''m looking exactly onto the wall, and it kind of cuts the photo in half.  i think it''s because you probably wanted to get in both the window display and the street.  <br/>overall -- 5 from gr8photos</td>', 'challenge -- mettechnical -- good.  i do wonder though why you chose b&w.  but maybe it would be clear if i saw the color version ;)composition -- i''m not sure exactly how i would change this, but i feel that i''m looking exactly onto the wall, and it kind of cuts the photo in half.  i think it''s because you probably wanted to get in both the window display and the street.  overall -- 5 from gr8photos', '2002-10-14 16:20:00.000000', NULL, 1),
(143111, 7138, 3859, '<td valign="top">Good depiction of some of the sins.  B &amp; W works very well here.</td>', 'Good depiction of some of the sins.  B & W works very well here.', '2002-10-14 17:05:00.000000', NULL, 1),
